catalogue={'version':1,'title':'Kabita Live design review','groups':[dict(id=i,title=t,status=s,heading=h,description=d,variants=[x for x in [a,b] if x],checks=c) for i,t,s,h,d,a,b,c in groups]}
(R/'design-system-catalogue.json').write_text(json.dumps(catalogue,ensure_ascii=False,indent=2))
